def B(t,lines,xy,tail,size=52,until=99,kind='round'): return {'t':t,'type':'bubble','lines':lines,'xy':xy,'tail':tail,'size':size,'until':until,'kind':kind}
def SH(t,lines,xy,tail,size=56,until=99): return B(t,lines,xy,tail,size,until,'shout')
def CAP(t,lines,xy,size=48,until=99): return {'t':t,'type':'cap','lines':lines,'xy':xy,'size':size,'until':until}
def SFX(t,text,xy,size=160,angle=-12): return {'t':t,'type':'sfx','text':text,'xy':xy,'size':size,'angle':angle}
def S(img,ax,ev,fx=None,sec=6):
    d={'img':R+img,'ax':ax,'events':ev,'sec':sec}
    if fx: d['lines_fx']=0.0; d['fx_center']=fx
    return d

